```java
import java.util.Arrays;

public class DuplicateFinder {
    public static void findDuplicates(int[] nums) {
        if (nums == null || nums.length < 2) return;
        int n = nums.length;
        // Step 1: Mark visited elements by negating value at index
        for (int i = 0; i < n; i++) {
            int index = Math.abs(nums[i]) - 1;
            if (nums[index] < 0) {
                // Already visited
                int duplicateIdx = Math.abs(index) - 1;
                if (duplicateIdx >= 0 && duplicateIdx < n) {
                    nums[duplicateIdx] = Math.abs(nums[duplicateIdx]) + n; // Mark as seen at end
                }
            } else {
                nums[index] = -nums[index];
            }
        }
        // Step 2: Collect duplicates
        List<Integer> duplicates = new ArrayList<>();
        for (int i = 0; i < n; i++) {
            int val = Math.abs(nums[i]);
            if (nums[i] > 0 && val >= n) {
                duplicates.add(val);
            }
        }
        System.out.println("Duplicates: " + duplicates);
    }

    public static void main(String[] args) {
        int[] arr = {4, 3, 6, 2, 1, 4, 3};
        findDuplicates(arr);
        System.out.println(Arrays.toString(arr));
    }
}
```

