class MainViewController: UIViewController, ObservableObject {
    @Published var habits: [Habit] = []
    @State var newHabitName: String? = ""
    @State var newHabitDesc: String? = ""

    let habitContext = HabitContext()
    let habitEntity = HabitEntity()

    var viewModels: [HabitViewModel] = []

    override func viewDidLoad() {
        super.viewDidLoad()
        loadHabits()
        setupUI()
    }

    func loadHabits() {
        let fetchRequest: NSFetchRequest<Habit> (<#NSManagedObjectType#>) = fetchRequest(for: self.habitContext)
        fetchRequest.fetchRequest?.sortDescriptor = NSSortDescriptor(keyPath: "lastUpdated", ascending: false)
        do {
            self.viewModels = try self.viewContext.fetch(fetchRequest).map { habit in
                HabitViewModel(habit: habit)
            }
        } catch {
            print("Error loading habits: \(error)")
        }
    }

    func addHabit() {
        if let name = newHabitName, let desc = newHabitDesc {
            let habit = HabitsModel(habitName: name, habitDesc: desc)
            performAddHabit(with: habit)
            newHabitName = nil
            newHabitDesc = nil
            loadHabits()
        }
    }

    func performAddHabit(with habit: HabitsModel) {
        let context = NSManagedObjectContext(concurrencyType: .main)
        context.setEntity(forObject: habitEntity, in: context)
        context.insert(habit as NSManagedObject)
        do {
            try context.save()
            let fetchRequest = NSFetchRequest<Habit>(entityName: "Habit")
            let newHabits = try context.fetch(fetchRequest)
            self.habits.append(contentsOf: newHabits)
        } catch {
            print("Add error: \(error)")
        }
    }

    func updateHabit(_ index: Int, isCompleted: Bool) {
        if let habit = viewModels.indices.contains(index) ? viewModels[index].habit : nil {
            let context = NSManagedObjectContext(concurrencyType: .main)
            context.setEntity(forObject: habitEntity, in: context)
            let habitObj = NSManagedObject(object: habit as Any)
            habitObj.setValue(isCompleted, forKey: "isCompleted")
            habitObj.setValue(Date().date, forKey: "lastUpdated")
            do {
                try context.save()
                let fetchRequest = NSFetchRequest<Habit>(entityName: "Habit")
                let updated = try context.fetch(fetchRequest).filter { $0.isCompleted == isCompleted && $0.name == habit.name }
                if let updatedObj = updated.first as? NSManagedObject {
                    // Update in place
                    updatedObj.setValue(habitObj, forKey: "isCompleted")
                    updatedObj.setValue(habitObj, forKey: "lastUpdated")
                } else {
                    context.insert(habitObj)
                }
                loadHabits()
            } catch {
                print("Update error: \(error)")
            }
        }
    }

    func deleteHabit(_ index: Int) {
        if let habit = viewModels.indices.contains(index) ? viewModels[index].habit : nil {
            let context = NSManagedObjectContext(concurrencyType: .main)
            context.setEntity(forObject: habitEntity, in: context)
            let fetchRequest = NSFetchRequest<NSManagedObject>(entityName: "Habit")
            fetchRequest.addFetchPath("name == \(habit.name)")
            do {
                let objects = try context.fetch(fetchRequest)
                for obj in objects {
                    context.deleteObject(obj as NSManagedObject)
                }
                try context.save()
                loadHabits()
            } catch {
                print("Delete error: \(error)")
            }
        }
    }

