from collections import OrderedDict

def main():
    import sys
    input_lines = sys.stdin.read().splitlines()
    if not input_lines:
        return
    capacity = int(input_lines[0].strip())
    n = int(input_lines[1].strip())
    operations = [line.strip().split() for line in input_lines[2:2+n]]

    cache = OrderedDict()
    for op in operations:
        if not op:
            continue
        if op[0] == 'put':
            key = int(op[1])
            value = int(op[2])
            if key in cache:
                # Move to end to mark as recently used
                cache.move_to_end(key)
            cache[key] = value
            if len(cache) > capacity:
                cache.popitem(last=False)  # Remove least recently used
        elif op[0] == 'get':
            key = int(op[1])
            if key in cache:
                # Move to end to mark as recently used
                cache.move_to_end(key)
                print(cache[key])
            else:
                print(-1)

