#include <iostream>
#include <vector>
#include <memory>
#include <algorithm>

// Define a simple class for a person
class Person {
public:
    std::string name;
    int age;

    Person(const std::string& n, int a) : name(n), age(a) {}

    // Overload operator< for sorting by age
    bool operator<(const Person& other) const {
        return age < other.age;
    }

    // Helper function to print person info
    void print() const {
        std::cout << name << " is " << age << " years old." << std::endl;
    }
};

int main() {
    // Use std::make_unique for smart pointers (not strictly necessary here, but good practice)
    std::vector<std::unique_ptr<Person>> people{
        std::make_unique<Person>("Alice", 30),
        std::make_unique<Person>("Bob", 25),
        std::make_unique<Person>("Charlie", 35)
    };

    // Sort the vector of unique pointers using a lambda that dereferences and compares by age
    std::sort(
        people.begin(),
        people.end(),
        [](const std::unique_ptr<Person>& a, const std::unique_ptr<Person>& b) {
            return a->age < b->age;
        }
    );

    // Use a range-based for loop to print each person
    for (const auto& person : people) {
        person->print();
    }

    return 0;
}
